SET LOCAL search_path TO stockroom, public;
CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 150),slug text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','suspended','closed')),currency_code char(3) NOT NULL DEFAULT 'INR',timezone text NOT NULL DEFAULT 'Asia/Kolkata',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id));
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL,password_hash text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','disabled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX users_email_normalized_uq ON users(lower(email));
CREATE TABLE roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),key text NOT NULL UNIQUE,name text NOT NULL);
CREATE TABLE permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),key text NOT NULL UNIQUE,description text NOT NULL);
CREATE TABLE role_permissions(role_id uuid NOT NULL REFERENCES roles(id),permission_id uuid NOT NULL REFERENCES permissions(id),PRIMARY KEY(role_id,permission_id));
INSERT INTO roles(key,name) VALUES('tenant_owner','Tenant owner'),('administrator','Administrator'),('branch_manager','Branch manager'),('warehouse_operator','Warehouse operator'),('sales_staff','Sales staff'),('purchasing_staff','Purchasing staff'),('viewer','Viewer') ON CONFLICT(key) DO NOTHING;
INSERT INTO permissions(key,description) VALUES('catalog.read','Read catalog'),('catalog.manage','Manage catalog'),('contacts.read','Read contacts'),('contacts.manage','Manage contacts'),('purchases.read','Read purchases'),('purchases.create','Create purchases'),('purchases.confirm','Confirm purchases'),('receipts.post','Post receipts'),('sales.read','Read sales'),('sales.create','Create sales'),('sales.confirm','Confirm sales'),('dispatches.post','Post dispatches'),('stock.read','Read stock'),('transfers.create','Create transfers'),('transfers.ship','Ship transfers'),('transfers.receive','Receive transfers'),('counts.create','Create counts'),('counts.enter','Enter counts'),('counts.approve','Approve counts'),('adjustments.post','Post adjustments'),('reports.read','Read reports'),('reports.cost.read','Read costs'),('exports.create','Create exports'),('locations.read','Read locations'),('locations.manage','Manage locations'),('members.read','Read members'),('members.manage','Manage members'),('settings.manage','Manage settings'),('audit.read','Read audit'),('ownership.transfer','Transfer ownership') ON CONFLICT(key) DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.key IN('tenant_owner','administrator') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r JOIN permissions p ON p.key IN('catalog.read','contacts.read','contacts.manage','purchases.read','purchases.create','purchases.confirm','receipts.post','stock.read','reports.read') WHERE r.key='purchasing_staff' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r JOIN permissions p ON p.key IN('catalog.read','contacts.read','sales.read','sales.create','sales.confirm','dispatches.post','stock.read','reports.read') WHERE r.key='sales_staff' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r JOIN permissions p ON p.key IN('catalog.read','stock.read','receipts.post','dispatches.post','transfers.create','transfers.ship','transfers.receive','counts.create','counts.enter') WHERE r.key='warehouse_operator' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r JOIN permissions p ON p.key IN('catalog.read','contacts.read','purchases.read','sales.read','stock.read','reports.read','locations.read') WHERE r.key='viewer' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r JOIN permissions p ON p.key NOT IN('members.manage','ownership.transfer','reports.cost.read') WHERE r.key='branch_manager' ON CONFLICT DO NOTHING;
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked_at timestamptz,last_seen_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_expiry_idx ON sessions(user_id,expires_at);
CREATE TABLE memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL REFERENCES users(id),role_id uuid NOT NULL REFERENCES roles(id),status text NOT NULL DEFAULT 'invited' CHECK(status IN('invited','active','suspended','removed')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id),UNIQUE(tenant_id,id));
CREATE INDEX memberships_user_status_idx ON memberships(user_id,status);
CREATE TABLE invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),email text NOT NULL,role_id uuid NOT NULL REFERENCES roles(id),token_hash text NOT NULL UNIQUE,invited_by uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL,accepted_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE INDEX invitations_tenant_email_expiry_idx ON invitations(tenant_id,lower(email),expires_at) WHERE accepted_at IS NULL AND revoked_at IS NULL;
CREATE TABLE branches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),code text,name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 150),address text,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','archived')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE UNIQUE INDEX branches_code_uq ON branches(tenant_id,upper(code)) WHERE code IS NOT NULL;
CREATE UNIQUE INDEX branches_active_name_uq ON branches(tenant_id,lower(name)) WHERE status='active';
CREATE TABLE warehouses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),branch_id uuid NOT NULL,code text,name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 150),address text,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','archived')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE UNIQUE INDEX warehouses_code_uq ON warehouses(tenant_id,branch_id,upper(code)) WHERE code IS NOT NULL;
CREATE UNIQUE INDEX warehouses_active_name_uq ON warehouses(tenant_id,branch_id,lower(name)) WHERE status='active';
CREATE TABLE membership_branch_scopes(tenant_id uuid NOT NULL,membership_id uuid NOT NULL,branch_id uuid NOT NULL,PRIMARY KEY(tenant_id,membership_id,branch_id),FOREIGN KEY(tenant_id,membership_id) REFERENCES memberships(tenant_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE membership_warehouse_scopes(tenant_id uuid NOT NULL,membership_id uuid NOT NULL,warehouse_id uuid NOT NULL,PRIMARY KEY(tenant_id,membership_id,warehouse_id),FOREIGN KEY(tenant_id,membership_id) REFERENCES memberships(tenant_id,id),FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id));
CREATE TABLE units(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,name text NOT NULL,allows_fraction boolean NOT NULL DEFAULT false);
INSERT INTO units(code,name,allows_fraction) VALUES('piece','Piece',false),('box','Box',false),('kg','Kg',true),('g','Gram',true),('l','Litre',true),('m','Meter',true) ON CONFLICT(code) DO NOTHING;
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),sku text NOT NULL,name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 150),unit_id uuid NOT NULL REFERENCES units(id),barcode text,category text,tax_treatment text CHECK(tax_treatment IN('taxable','exempt','nil-rated','non-gst')),hsn_code text,gst_rate numeric(5,2) CHECK(gst_rate BETWEEN 0 AND 100),cess_rate numeric(5,2) CHECK(cess_rate BETWEEN 0 AND 100),track_batches boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','archived')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE UNIQUE INDEX products_sku_uq ON products(tenant_id,lower(sku));
CREATE UNIQUE INDEX products_barcode_uq ON products(tenant_id,barcode) WHERE barcode IS NOT NULL;
CREATE INDEX products_tenant_status_name_idx ON products(tenant_id,status,name,id);
CREATE TABLE product_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,product_id uuid NOT NULL,batch_number text NOT NULL CHECK(length(btrim(batch_number)) BETWEEN 1 AND 80),manufactured_on date,expires_on date,mrp numeric(18,4) CHECK(mrp IS NULL OR mrp>=0),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','archived')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id),CHECK(manufactured_on IS NULL OR expires_on IS NULL OR expires_on>=manufactured_on));
CREATE UNIQUE INDEX product_batches_number_uq ON product_batches(tenant_id,product_id,lower(batch_number));
CREATE INDEX product_batches_expiry_idx ON product_batches(tenant_id,expires_on,product_id) WHERE expires_on IS NOT NULL AND status='active';
CREATE TABLE contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 150),email text,mobile text,gstin text,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','archived')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE INDEX contacts_tenant_name_idx ON contacts(tenant_id,status,name);
CREATE TABLE contact_roles(tenant_id uuid NOT NULL,contact_id uuid NOT NULL,role text NOT NULL CHECK(role IN('supplier','customer')),PRIMARY KEY(tenant_id,contact_id,role),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id));
CREATE TABLE contact_addresses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,contact_id uuid NOT NULL,label text,address text,city text,state text,postal_code text,country_code char(2) DEFAULT 'IN',is_default boolean NOT NULL DEFAULT false,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id));
CREATE UNIQUE INDEX contact_default_address_uq ON contact_addresses(tenant_id,contact_id) WHERE is_default;
CREATE TABLE purchase_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),order_number text NOT NULL,supplier_id uuid NOT NULL,warehouse_id uuid NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','confirmed','partially_received','closed','cancelled')),ordered_on date NOT NULL DEFAULT current_date,expected_on date,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,order_number),FOREIGN KEY(tenant_id,supplier_id) REFERENCES contacts(tenant_id,id),FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id));
CREATE TABLE purchase_order_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,purchase_order_id uuid NOT NULL,line_number integer NOT NULL CHECK(line_number>0),product_id uuid NOT NULL,ordered_quantity numeric(18,3) NOT NULL CHECK(ordered_quantity>0),unit_cost_estimate numeric(18,4) CHECK(unit_cost_estimate IS NULL OR unit_cost_estimate>=0),UNIQUE(tenant_id,id),UNIQUE(purchase_order_id,line_number),FOREIGN KEY(tenant_id,purchase_order_id) REFERENCES purchase_orders(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id));
CREATE TABLE sales_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),order_number text NOT NULL,customer_id uuid NOT NULL,warehouse_id uuid NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','confirmed','partially_dispatched','closed','cancelled')),ordered_on date NOT NULL DEFAULT current_date,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,order_number),FOREIGN KEY(tenant_id,customer_id) REFERENCES contacts(tenant_id,id),FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id));
CREATE TABLE sales_order_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,sales_order_id uuid NOT NULL,line_number integer NOT NULL CHECK(line_number>0),product_id uuid NOT NULL,ordered_quantity numeric(18,3) NOT NULL CHECK(ordered_quantity>0),unit_price numeric(18,4) CHECK(unit_price IS NULL OR unit_price>=0),UNIQUE(tenant_id,id),UNIQUE(sales_order_id,line_number),FOREIGN KEY(tenant_id,sales_order_id) REFERENCES sales_orders(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id));
CREATE TABLE stock_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),document_type text NOT NULL CHECK(document_type IN('opening_stock','adjustment','purchase_receipt','dispatch','transfer','count_adjustment','supplier_return','customer_return')),document_number text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','posted','in_transit','partially_received','received','cancelled')),business_date date NOT NULL DEFAULT current_date,warehouse_id uuid,source_warehouse_id uuid,destination_warehouse_id uuid,contact_id uuid,idempotency_key text,version integer NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES users(id),posted_by uuid REFERENCES users(id),posted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,document_type,document_number),UNIQUE(tenant_id,idempotency_key),FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id),FOREIGN KEY(tenant_id,source_warehouse_id) REFERENCES warehouses(tenant_id,id),FOREIGN KEY(tenant_id,destination_warehouse_id) REFERENCES warehouses(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id),CHECK(source_warehouse_id IS NULL OR destination_warehouse_id IS NULL OR source_warehouse_id<>destination_warehouse_id));
CREATE INDEX stock_documents_tenant_type_status_date_idx ON stock_documents(tenant_id,document_type,status,business_date DESC,id);
CREATE TABLE stock_document_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,document_id uuid NOT NULL,line_number integer NOT NULL CHECK(line_number>0),product_id uuid NOT NULL,product_batch_id uuid,quantity numeric(18,3) NOT NULL CHECK(quantity>0),acquisition_unit_cost numeric(18,4) CHECK(acquisition_unit_cost IS NULL OR acquisition_unit_cost>=0),mrp numeric(18,4) CHECK(mrp IS NULL OR mrp>=0),purchase_order_line_id uuid,sales_order_line_id uuid,source_document_line_id uuid,UNIQUE(tenant_id,id),UNIQUE(document_id,line_number),FOREIGN KEY(tenant_id,document_id) REFERENCES stock_documents(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id),FOREIGN KEY(tenant_id,product_batch_id) REFERENCES product_batches(tenant_id,id),FOREIGN KEY(tenant_id,purchase_order_line_id) REFERENCES purchase_order_lines(tenant_id,id),FOREIGN KEY(tenant_id,sales_order_line_id) REFERENCES sales_order_lines(tenant_id,id),FOREIGN KEY(tenant_id,source_document_line_id) REFERENCES stock_document_lines(tenant_id,id));
CREATE TABLE purchase_receipts(stock_document_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,purchase_order_id uuid,supplier_id uuid NOT NULL,supplier_reference text,UNIQUE(tenant_id,stock_document_id),FOREIGN KEY(tenant_id,stock_document_id) REFERENCES stock_documents(tenant_id,id),FOREIGN KEY(tenant_id,purchase_order_id) REFERENCES purchase_orders(tenant_id,id),FOREIGN KEY(tenant_id,supplier_id) REFERENCES contacts(tenant_id,id));
CREATE TABLE purchase_receipt_lines(stock_document_line_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,purchase_order_line_id uuid,UNIQUE(tenant_id,stock_document_line_id),FOREIGN KEY(tenant_id,stock_document_line_id) REFERENCES stock_document_lines(tenant_id,id),FOREIGN KEY(tenant_id,purchase_order_line_id) REFERENCES purchase_order_lines(tenant_id,id));
CREATE TABLE dispatches(stock_document_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,sales_order_id uuid,customer_id uuid NOT NULL,UNIQUE(tenant_id,stock_document_id),FOREIGN KEY(tenant_id,stock_document_id) REFERENCES stock_documents(tenant_id,id),FOREIGN KEY(tenant_id,sales_order_id) REFERENCES sales_orders(tenant_id,id),FOREIGN KEY(tenant_id,customer_id) REFERENCES contacts(tenant_id,id));
CREATE TABLE dispatch_lines(stock_document_line_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,sales_order_line_id uuid,UNIQUE(tenant_id,stock_document_line_id),FOREIGN KEY(tenant_id,stock_document_line_id) REFERENCES stock_document_lines(tenant_id,id),FOREIGN KEY(tenant_id,sales_order_line_id) REFERENCES sales_order_lines(tenant_id,id));
CREATE TABLE stock_transfers(stock_document_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,shipped_at timestamptz,received_at timestamptz,UNIQUE(tenant_id,stock_document_id),FOREIGN KEY(tenant_id,stock_document_id) REFERENCES stock_documents(tenant_id,id),CHECK(received_at IS NULL OR shipped_at IS NOT NULL));
CREATE TABLE stock_transfer_lines(stock_document_line_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,shipped_quantity numeric(18,3) CHECK(shipped_quantity IS NULL OR shipped_quantity>0),received_quantity numeric(18,3) CHECK(received_quantity IS NULL OR received_quantity>=0),discrepancy_note text,UNIQUE(tenant_id,stock_document_line_id),FOREIGN KEY(tenant_id,stock_document_line_id) REFERENCES stock_document_lines(tenant_id,id),CHECK(received_quantity IS NULL OR shipped_quantity IS NOT NULL));
CREATE TABLE transfer_in_transit_balances(tenant_id uuid NOT NULL,stock_document_line_id uuid NOT NULL,quantity numeric(18,3) NOT NULL CHECK(quantity>=0),inventory_value numeric(18,4) NOT NULL DEFAULT 0 CHECK(inventory_value>=0),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,stock_document_line_id),FOREIGN KEY(tenant_id,stock_document_line_id) REFERENCES stock_transfer_lines(tenant_id,stock_document_line_id));
CREATE TABLE stock_counts(stock_document_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,count_status text NOT NULL DEFAULT 'in_progress' CHECK(count_status IN('in_progress','submitted','approved','cancelled')),started_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz,UNIQUE(tenant_id,stock_document_id),FOREIGN KEY(tenant_id,stock_document_id) REFERENCES stock_documents(tenant_id,id));
CREATE TABLE stock_count_lines(stock_document_line_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,expected_quantity numeric(18,3) NOT NULL CHECK(expected_quantity>=0),counted_quantity numeric(18,3) CHECK(counted_quantity IS NULL OR counted_quantity>=0),UNIQUE(tenant_id,stock_document_line_id),FOREIGN KEY(tenant_id,stock_document_line_id) REFERENCES stock_document_lines(tenant_id,id));
CREATE TABLE returns(stock_document_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,original_document_id uuid NOT NULL,return_kind text NOT NULL CHECK(return_kind IN('supplier','customer')),UNIQUE(tenant_id,stock_document_id),FOREIGN KEY(tenant_id,stock_document_id) REFERENCES stock_documents(tenant_id,id),FOREIGN KEY(tenant_id,original_document_id) REFERENCES stock_documents(tenant_id,id));
CREATE TABLE return_lines(stock_document_line_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,original_document_line_id uuid NOT NULL,disposition text NOT NULL CHECK(disposition IN('sellable','quarantine','damaged')),UNIQUE(tenant_id,stock_document_line_id),FOREIGN KEY(tenant_id,stock_document_line_id) REFERENCES stock_document_lines(tenant_id,id),FOREIGN KEY(tenant_id,original_document_line_id) REFERENCES stock_document_lines(tenant_id,id));
CREATE TABLE stock_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),document_line_id uuid NOT NULL,warehouse_id uuid,product_id uuid NOT NULL,product_batch_id uuid,transfer_line_id uuid,location_type text NOT NULL DEFAULT 'warehouse' CHECK(location_type IN('warehouse','in_transit')),event_type text NOT NULL CHECK(event_type IN('receipt','issue','transfer_ship','transfer_receive','adjustment','return','reversal')),quantity_delta numeric(18,3) NOT NULL CHECK(quantity_delta<>0),unit_cost numeric(18,4) CHECK(unit_cost IS NULL OR unit_cost>=0),value_delta numeric(18,4) NOT NULL DEFAULT 0,business_date date NOT NULL,posted_at timestamptz NOT NULL DEFAULT now(),actor_id uuid NOT NULL REFERENCES users(id),posting_key text NOT NULL,reverses_movement_id uuid,UNIQUE(tenant_id,id),UNIQUE(tenant_id,posting_key),FOREIGN KEY(tenant_id,document_line_id) REFERENCES stock_document_lines(tenant_id,id),FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id),FOREIGN KEY(tenant_id,product_batch_id) REFERENCES product_batches(tenant_id,id),FOREIGN KEY(tenant_id,transfer_line_id) REFERENCES stock_transfer_lines(tenant_id,stock_document_line_id),FOREIGN KEY(tenant_id,reverses_movement_id) REFERENCES stock_movements(tenant_id,id),CHECK((location_type='warehouse' AND warehouse_id IS NOT NULL) OR (location_type='in_transit' AND warehouse_id IS NULL AND transfer_line_id IS NOT NULL)));
CREATE INDEX stock_movements_product_history_idx ON stock_movements(tenant_id,warehouse_id,product_id,posted_at DESC,id DESC);
CREATE INDEX stock_movements_tenant_posted_idx ON stock_movements(tenant_id,posted_at DESC,id DESC);
CREATE TABLE stock_balances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,warehouse_id uuid NOT NULL,product_id uuid NOT NULL,product_batch_id uuid,quantity_on_hand numeric(18,3) NOT NULL DEFAULT 0 CHECK(quantity_on_hand>=0),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id),FOREIGN KEY(tenant_id,product_batch_id) REFERENCES product_batches(tenant_id,id));
CREATE UNIQUE INDEX stock_balances_nonbatch_uq ON stock_balances(tenant_id,warehouse_id,product_id) WHERE product_batch_id IS NULL;
CREATE UNIQUE INDEX stock_balances_batch_uq ON stock_balances(tenant_id,warehouse_id,product_id,product_batch_id) WHERE product_batch_id IS NOT NULL;
CREATE INDEX stock_balances_product_location_idx ON stock_balances(tenant_id,product_id,warehouse_id);
CREATE TABLE stock_valuations(tenant_id uuid NOT NULL,warehouse_id uuid NOT NULL,product_id uuid NOT NULL,quantity_on_hand numeric(18,3) NOT NULL DEFAULT 0 CHECK(quantity_on_hand>=0),inventory_value numeric(18,4) NOT NULL DEFAULT 0 CHECK(inventory_value>=0),average_unit_cost numeric(18,4) NOT NULL DEFAULT 0 CHECK(average_unit_cost>=0),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,warehouse_id,product_id),FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id));
CREATE TABLE stock_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,sales_order_line_id uuid NOT NULL,warehouse_id uuid NOT NULL,product_id uuid NOT NULL,product_batch_id uuid,quantity numeric(18,3) NOT NULL CHECK(quantity>0),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','released','fulfilled','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,sales_order_line_id) REFERENCES sales_order_lines(tenant_id,id),FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id),FOREIGN KEY(tenant_id,product_batch_id) REFERENCES product_batches(tenant_id,id));
CREATE INDEX stock_reservations_location_product_idx ON stock_reservations(tenant_id,warehouse_id,product_id,status);
CREATE TABLE document_number_sequences(tenant_id uuid NOT NULL REFERENCES tenants(id),document_type text NOT NULL,series text NOT NULL DEFAULT 'default',next_value bigint NOT NULL DEFAULT 1 CHECK(next_value>0),prefix text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,document_type,series));
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),actor_id uuid REFERENCES users(id),action text NOT NULL,entity_type text NOT NULL,entity_id uuid,occurred_at timestamptz NOT NULL DEFAULT now(),request_id text,summary jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX audit_events_timeline_idx ON audit_events(tenant_id,occurred_at DESC,id DESC);
CREATE INDEX audit_events_entity_idx ON audit_events(tenant_id,entity_type,entity_id,occurred_at DESC);